#include <float.h>
#include <limits.h>
static void FloatGolden(const char *spelling,float expected){char text[1400];bot_character_t *ch;snprintf(text,sizeof(text),"skill 4 { 79 \"owned\" 1 %s }",spelling);Reset(text);ch=BotLoadCharacterFromFile("bots/native.c",4);if(!ch)fprintf(stderr,"Rejected valid float spelling: %s\n",spelling);Check(ch&&ch->c[1].type==CT_FLOAT&&!memcmp(&ch->c[1].value._float,&expected,sizeof(expected))&&ch->c[79].type==CT_STRING&&!strcmp(ch->c[79].value.string,"owned"),"native representable lexer float publishes exact stored value and prior string");Check(liveOwners==2&&!numtokens&&!errors&&!warnings&&opens==1&&closes==1,"valid float publication closes/releases every source owner");botcharacters[1]=ch;Check(Characteristic_Float(1,1)==expected,"public float getter retains parsed native value");BotFreeCharacter2(1);Check(!liveOwners&&!numtokens,"valid float/string owner cleanup physically releases all");}
static const char *catalogRoot,*catalogLeaf;
static int FloatCatalogOpen(const char *path,fileHandle_t *file,fsMode_t mode){const char *base=strrchr(path,'/');base=base?base+1:path;fileText=!strcmp(base,"float.inc")?catalogLeaf:catalogRoot;return Open(path,file,mode);}
static void FloatFailure(int mode,int digits){char spelling[1024],text[1400];bot_character_t *ch;int expectedFiles=mode==2?2:1;memset(spelling,'9',digits);memcpy(spelling+digits,".0",3);if(mode==1)snprintf(text,sizeof(text),"#define huge %s\nskill 4 { 79 \"owned\" 0 1.25 1 huge }",spelling);else snprintf(text,sizeof(text),"skill 4 { 79 \"owned\" 0 1.25 1 %s }",spelling);Reset(mode==2?"#include \"float.inc\"":text);if(mode==2){catalogRoot=fileText;catalogLeaf=text;botimport.FS_FOpenFile=FloatCatalogOpen;}ch=BotLoadCharacterFromFile("bots/native.c",4);Check(!ch,"out-of-range lexer float rejects private character publication");Check(!liveOwners&&!numtokens&&errors==1&&opens==expectedFiles&&fileReads==expectedFiles&&closes==expectedFiles,"failed direct/macro/included float frees prior strings and all source/dictionary/token owners");Reset("skill 4 { 79 \"owned\" 1 1.25 }");ch=BotLoadCharacterFromFile("bots/native.c",4);Check(ch&&ch->c[1].value._float==1.25f,"failed float character load retries");Release(ch);}
static void WordFailure(int base,int mode){const char *spelling[]={"4294967296","0x100000000","040000000000","0b100000000000000000000000000000000"};char text[256];bot_character_t *ch;if(mode==1)snprintf(text,sizeof(text),"#define huge %s\nskill 4 { 79 \"owned\" 0 1.25 1 huge }",spelling[base]);else snprintf(text,sizeof(text),"skill 4 { 79 \"owned\" 0 1.25 1 %s }",spelling[base]);Reset(mode==2?"#include \"float.inc\"":text);if(mode==2){catalogRoot=fileText;catalogLeaf=text;botimport.FS_FOpenFile=FloatCatalogOpen;}ch=BotLoadCharacterFromFile("bots/native.c",4);Check(!ch,"oversized native integer word rejects before narrowing/publication");Check(!liveOwners&&!numtokens&&errors>0&&opens==(mode==2?2:1)&&closes==opens,"oversized word releases every private prior string/source/macro owner");}
static void NativeWords(void){const char *values[]={"2147483647","2147483648","4294967295"};int expected[]={INT_MAX,INT_MIN,-1};char text[128];bot_character_t *ch;int i;for(i=0;i<3;i++){snprintf(text,sizeof(text),"skill 4 { 0 %s }",values[i]);Reset(text);ch=BotLoadCharacterFromFile("bots/native.c",4);Check(ch&&ch->c[0].type==CT_INTEGER&&ch->c[0].value.integer==expected[i]&&!errors,"native 32-bit integer word/sign patterns remain unchanged");Release(ch);}}
static void Ordinary(void){FloatGolden("1.25",1.25f);FloatGolden("0.5",0.5f);FloatGolden(".5",0.5f);FloatGolden("0.001",0.001f);FloatGolden("0.",0.0f);FloatGolden("1.",1.0f);FloatGolden("1.25l",1.25f);FloatGolden("2147483648.0",2147483648.0f);FloatGolden("340282346638528859811704183484516925440.0",FLT_MAX);FloatGolden("0.00000000000000000000000000000000000000000000140129846432481707092372958328991613128026194187651577175706828388979108268586060148663818836212158203125",strtof("0.00000000000000000000000000000000000000000000140129846432481707092372958328991613128026194187651577175706828388979108268586060148663818836212158203125",NULL));NativeWords();}
int main(int argc,char **argv){if(argc>1){int proof=atoi(argv[1]);if(proof<3)FloatFailure(proof,80);else if(proof==3)FloatFailure(0,1000);else if(proof<8)WordFailure(proof-4,0);else if(proof<10)WordFailure(0,proof-7);else Ordinary();}else{int base;Ordinary();FloatFailure(0,80);FloatFailure(1,80);FloatFailure(2,80);FloatFailure(0,1000);for(base=0;base<4;base++)WordFailure(base,0);WordFailure(0,1);WordFailure(0,2);puts("Real character numeric publication, native range/word values and private failure cleanup passed (issue #48)");}return 0;}
